<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue';
import { brewApi } from '../api';
import { locationPathLabel } from '../location-label';
import { countReasons, hasCount, countDelta, countStatus, countPayload, countValidation, countQuantityGroups } from '../inventory-count';
import JourneyDetailDialog from './JourneyDetailDialog.vue';

const props = defineProps({ permissions:{type:Array,default:()=>[]}, initialId:[String,Number], taskOnly:Boolean });
const emit = defineEmits(['toast','changed','close']);
const records=ref([]),total=ref(0),page=ref(1),loading=ref(false),saving=ref(false),error=ref('');
const filters=reactive({keyword:'',factory_id:'',state:''});
const options=ref({factories:[],locations:[],products:[],lots:[]});
const record=ref(null),lines=ref([]),phase=ref('entry'),mode=ref('all'),keyword=ref(''),dirty=ref(false),lastSaved=ref('');
const dialog=ref(''),dialogError=ref(''),selectedLine=ref(null),panel=ref(null),dialogDraft=reactive({});
let listSequence=0,detailSequence=0,optionsSequence=0;
const canManage=computed(()=>props.permissions.some(p=>['inventory.count.manage','admin.user.manage','base.master_data.manage'].includes(p)));
const editable=computed(()=>canManage.value && record.value?.can_edit);
const differences=computed(()=>lines.value.filter(line=>countDelta(line)));
const counted=computed(()=>lines.value.filter(hasCount).length);
const activeStep=computed(()=>record.value?.approvals?.flatMap(instance=>instance.steps).find(step=>step.can_act));
const listLocations=computed(()=>options.value.locations.filter(loc=>!dialogDraft.factory_id||String(loc.factory_id)===String(dialogDraft.factory_id)));
const addLocations=computed(()=>options.value.locations.filter(loc=>String(loc.factory_id)===String(record.value?.factory?.id)&&(
  loc.id===record.value.location.id || loc.name.startsWith(record.value.location.name+'/') || loc.name.startsWith(record.value.location.name+' / ')
)));
const visibleLines=computed(()=>{
  const search=keyword.value.trim().toLowerCase();
  return lines.value.filter(line=>{
    if(phase.value==='review'&&!countDelta(line))return false;
    if(phase.value==='entry'&&mode.value==='uncounted'&&hasCount(line))return false;
    if(phase.value==='entry'&&mode.value==='difference'&&!countDelta(line))return false;
    return !search || [line.product?.name,line.product?.code,line.lot?.name,line.location?.name].some(v=>String(v||'').toLowerCase().includes(search));
  });
});
const groups=computed(()=>countQuantityGroups(lines.value));
const number=v=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:6});
const time=v=>v?new Date(/[zZ]|[+-]\d\d:\d\d$/.test(v)?v:v+'Z').toLocaleString('zh-CN',{hour12:false}):'—';
const deltaText=line=>countDelta(line)===null?'—':(countDelta(line)>0?'+':'')+number(countDelta(line));
const primaryLabel=item=>item.state==='draft'?'开始盘点':item.can_edit?'继续盘点':item.approval_state==='approved'&&item.state==='pending_approval'?'核对入账':'查看';
function notify(message){emit('toast',message);}
function markDirty(){dirty.value=true;}
function adopt(data){record.value=data;lines.value=structuredClone(data.lines||[]);dirty.value=false;}
async function loadList(){
  const seq=++listSequence;loading.value=true;error.value='';
  try{const data=await brewApi.listInventoryCountPage({page:page.value,page_size:15,...Object.fromEntries(Object.entries(filters).filter(([,v])=>v))});if(seq!==listSequence)return;records.value=data.data;total.value=data.meta?.total||0;}
  catch(e){if(seq===listSequence)error.value=e.message;}finally{if(seq===listSequence)loading.value=false;}
}
async function loadOptions(params={}){
  const seq=++optionsSequence;try{const data=await brewApi.inventoryCountOptions(params);if(seq===optionsSequence)options.value=data;}catch(e){error.value=e.message;}
}
async function open(id){
  const seq=++detailSequence;loading.value=true;error.value='';
  try{const data=await brewApi.getInventoryCount(id);if(seq!==detailSequence)return;adopt(data);phase.value=data.can_edit?'entry':data.state==='pending_approval'?'review':'entry';mode.value='all';keyword.value='';lastSaved.value='';}
  catch(e){if(seq===detailSequence)error.value=e.message;}finally{if(seq===detailSequence)loading.value=false;}
}
function setDialog(type){
  dialogError.value='';Object.keys(dialogDraft).forEach(key=>delete dialogDraft[key]);
  if(type==='create'){dialogDraft.factory_id=options.value.factories.length===1?options.value.factories[0].id:'';dialogDraft.location_id='';}
  if(type==='add'){dialogDraft.location_id=record.value.location.id;dialogDraft.product_id='';dialogDraft.lot_id='';dialogDraft.counted_qty='';dialogDraft.difference_note='';loadOptions({factory_id:record.value.factory.id});}
  if(type==='line'){dialogDraft.counted_qty=selectedLine.value.counted_qty;dialogDraft.recount_note='';}
  dialog.value=type;
}
function closeDialog(){if(!saving.value)dialog.value='';}
function back(){if(dirty.value){setDialog('leave');return;}leave();}
function leave(){dialog.value='';if(props.taskOnly){emit('close');return;}record.value=null;lines.value=[];loadList();}
async function save(submit=false){
  if(saving.value)return;
  if(submit){const message=countValidation(lines.value);if(message){error.value=message;return;}}
  saving.value=true;error.value='';dialogError.value='';
  try{const result=await brewApi.updateInventoryCountLines(record.value.id,{version:record.value.version,lines:countPayload(lines.value),submit_after_save:submit});adopt(result);lastSaved.value=time(result.updated_at);dialog.value='';notify(submit?(result.state==='done'?'盘点完成，所选范围已恢复收发':'差异已提交审批'):'实盘已暂存');emit('changed');if(submit)phase.value=result.state==='done'?'entry':'review';}
  catch(e){error.value=e.message;dialogError.value=e.message;}finally{saving.value=false;}
}
function next(){const message=countValidation(lines.value,false);if(message){error.value=message;mode.value='uncounted';return;}error.value='';phase.value='review';keyword.value='';}
async function action(name,extra={}){
  if(saving.value)return;saving.value=true;dialogError.value='';error.value='';
  try{const result=await brewApi.inventoryCountAction(record.value.id,name,{version:record.value.version,...extra});adopt(result);dialog.value='';phase.value=result.can_edit?'entry':result.state==='pending_approval'?'review':'entry';notify(({start:'盘点已开始，所选范围暂停收发',cancel:'盘点已取消，所选范围已恢复收发',confirm:'差异已入账，所选范围已恢复收发'})[name]||'盘点单已更新');emit('changed');}
  catch(e){dialogError.value=e.message;error.value=e.message;}finally{saving.value=false;}
}
async function confirmDialog(){
  if(dialog.value==='start')return action('start');
  if(dialog.value==='post')return action('confirm');
  if(dialog.value==='submit')return save(true);
  if(dialog.value==='cancel'){if(!String(dialogDraft.reason||'').trim()){dialogError.value='请填写取消原因';return;}return action('cancel',{reason:dialogDraft.reason.trim()});}
  if(dialog.value==='line'){
    if(dialogDraft.counted_qty===''||!Number.isFinite(Number(dialogDraft.counted_qty))||Number(dialogDraft.counted_qty)<0||!String(dialogDraft.recount_note||'').trim()){dialogError.value='请填写有效的复盘数量和复盘说明';return;}
    if(!selectedLine.value.is_counted){dialogError.value='请先暂存首次实盘，再进行复盘';return;}
    selectedLine.value.counted_qty=Number(dialogDraft.counted_qty);selectedLine.value.recount_note=dialogDraft.recount_note.trim();dirty.value=true;dialog.value='';return;
  }
  if(!['create','add'].includes(dialog.value))return;
  saving.value=true;dialogError.value='';
  try{
    if(dialog.value==='create'){
      if(!dialogDraft.location_id)throw Error('请选择盘点库位');
      adopt(await brewApi.createInventoryCount({location_id:dialogDraft.location_id}));phase.value='entry';dialog.value='start';
    }else{
      if(dirty.value)throw Error('请先暂存当前实盘，再补录发现的库存');
      adopt(await brewApi.addInventoryCountLine(record.value.id,{version:record.value.version,...dialogDraft}));dialog.value='';notify('发现库存已补录，后续与差异一起审批');
    }
    emit('changed');
  }catch(e){dialogError.value=e.message;}finally{saving.value=false;}
}
async function review(actionName){
  if(!activeStep.value||saving.value)return;
  if(actionName==='return'&&!String(dialogDraft.comment||'').trim()){dialogError.value='请填写退回意见';return;}
  saving.value=true;dialogError.value='';
  try{await brewApi.approvalAction(activeStep.value.id,actionName,{version:activeStep.value.version,comment:dialogDraft.comment||''});await open(record.value.id);dialog.value='';emit('changed');notify(actionName==='approve'?'审批已通过，等待确认入账':'已退回修改');}
  catch(e){dialogError.value=e.message;}finally{saving.value=false;}
}
function focusNext(event){const inputs=[...panel.value.querySelectorAll('input[data-actual]')];const index=inputs.indexOf(event.target);inputs[index+1]?.focus();inputs[index+1]?.select();}
function beforeUnload(event){if(dirty.value){event.preventDefault();event.returnValue='';}}
onMounted(()=>{loadOptions();if(props.initialId)open(props.initialId);else loadList();window.addEventListener('beforeunload',beforeUnload);});
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));
</script>

<template>
<section ref="panel" class="count-page" :aria-busy="loading||saving">
  <div v-if="error" class="count-error" role="alert">{{ error }}<button v-if="!dirty" type="button" @click="record?open(record.id):loadList()">重新加载</button></div>
  <template v-if="!record">
    <header class="count-heading"><div><h2>库存盘点</h2><p>清点实物，核查差异。</p></div><button v-if="canManage" class="btn btn-primary" type="button" @click="setDialog('create')">＋ 新建盘点</button></header>
    <form class="count-filters" @submit.prevent="page=1;loadList()"><input v-model.trim="filters.keyword" aria-label="搜索盘点单" placeholder="搜索单号或库位"><select v-model="filters.factory_id" aria-label="盘点厂区"><option value="">全部厂区</option><option v-for="factory in options.factories" :key="factory.id" :value="factory.id">{{ factory.name }}</option></select><select v-model="filters.state" aria-label="盘点状态"><option value="">全部状态</option><option value="draft">未开始</option><option value="counting">盘点中</option><option value="pending_approval">待审批</option><option value="returned">已退回</option><option value="approved">待入账</option><option value="done">已完成</option><option value="cancelled">已取消</option></select><button class="btn btn-outline" type="submit" :disabled="loading">查询</button></form>
    <div class="count-table-wrap"><table class="count-table"><thead><tr><th>盘点单</th><th>范围</th><th>进度</th><th>差异</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="item in records" :key="item.id"><td><strong>{{ item.name }}</strong><small>{{ time(item.created_at) }}</small></td><td>{{ locationPathLabel(item.location) }}<small>{{ item.factory?.name }}</small></td><td>{{ item.counted_count }} / {{ item.line_count }} 项</td><td>{{ item.difference_count }} 项</td><td><span class="count-status" :class="item.state">{{ countStatus(item) }}</span></td><td><button class="btn btn-sm btn-outline" type="button" @click="open(item.id)">{{ primaryLabel(item) }}</button></td></tr><tr v-if="!records.length"><td colspan="6" class="count-empty">{{ loading?'正在加载…':'暂无盘点单' }}</td></tr></tbody></table></div>
    <footer class="count-pagination"><span>共 {{ total }} 张</span><div><button class="btn btn-xs btn-outline" :disabled="loading||page===1" @click="page--;loadList()">上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/15)) }}</span><button class="btn btn-xs btn-outline" :disabled="loading||page*15>=total" @click="page++;loadList()">下一页</button></div></footer>
  </template>
  <template v-else>
    <header class="count-heading detail"><div><button class="count-back" type="button" @click="back">← {{ taskOnly?'返回任务':'盘点列表' }}</button><div class="count-title"><h2>{{ locationPathLabel(record.location) }}</h2><span class="count-status" :class="record.state">{{ countStatus(record) }}</span></div><p>{{ record.name }}<span v-if="record.scope_locked" class="count-lock" :title="'该范围实际收发暂停，其他库位照常；完成或取消本单后恢复。'">· 本范围收发暂停 ⓘ</span></p></div><details class="count-more"><summary>更多 ···</summary><div><button type="button" @click="setDialog('history')">单据信息与记录</button><button v-if="editable" type="button" :disabled="dirty" @click="setDialog('add')" :title="dirty?'请先暂存当前录入':''">补录发现库存</button><button v-if="canManage && !['done','cancelled'].includes(record.state)" type="button" @click="setDialog('cancel')">取消本单</button></div></details></header>
    <div v-if="record.state==='draft'" class="count-empty-state"><h3>确认范围后开始盘点</h3><p>{{ locationPathLabel(record.location) }}，包含子库位。</p><p>开始后暂停此范围的实物收发，请同步安排现场清点。</p><button v-if="canManage" class="btn btn-primary" @click="setDialog('start')">开始盘点</button></div>
    <template v-else>
      <div v-if="!record.scope_locked && ['counting','pending_approval'].includes(record.state)" class="count-error">历史盘点单尚无有效冻结快照，请通过“更多”取消后重新新建。</div>
      <p v-if="record.approval_state==='returned'" class="count-return">审批退回：{{ record.approvals?.[0]?.steps.find(step=>step.state==='returned')?.comment || '请核查差异后重新提交' }}</p>
      <nav class="count-view-switch"><div><button v-if="editable" type="button" :class="{active:phase==='entry'}" @click="phase='entry'">实盘录入</button><button type="button" :class="{active:phase==='review'}" @click="editable?next():phase='review'">差异核查 <b>{{ differences.length }}</b></button><button v-if="!editable" type="button" :class="{active:phase==='entry'}" @click="phase='entry'">全部明细</button></div><span>{{ counted }} / {{ lines.length }} 项已盘</span></nav>
      <div class="count-line-tools"><input v-model.trim="keyword" aria-label="搜索商品或批次" placeholder="搜索商品、批次或库位"><div v-if="phase==='entry' && editable" class="count-filter-pills"><button v-for="[value,label] in [['all','全部'],['uncounted','未盘'],['difference','差异']]" :key="value" type="button" :class="{active:mode===value}" @click="mode=value">{{ label }}</button></div><span v-else class="count-review-caption">{{ differences.length?'核查差异后填写原因':'账实一致' }}</span></div>
      <div class="count-table-wrap"><table class="count-table count-lines"><thead><tr><th>商品 / 批次</th><th>账面</th><th>实盘</th><th>差异</th><th v-if="phase==='review'">差异原因</th><th></th></tr></thead><tbody><tr v-for="line in visibleLines" :key="line.id" :class="{different:countDelta(line)}"><td data-label="商品 / 批次"><strong>{{ line.product.name }}</strong><small>{{ line.lot?.name || '无批次' }}<template v-if="line.location.id!==record.location.id"> · {{ locationPathLabel(line.location) }}</template></small></td><td data-label="账面" class="count-number">{{ number(line.theoretical_qty) }} <span class="count-unit">{{ line.uom.name }}</span></td><td data-label="实盘" class="count-actual"><label v-if="editable && phase==='entry'"><input v-model="line.counted_qty" data-actual type="number" min="0" step="any" placeholder="未盘" :aria-label="line.product.name+'实盘数量'" @input="markDirty" @keydown.enter.prevent="focusNext"><span>{{ line.uom.name }}</span></label><span v-else>{{ hasCount(line)?number(line.counted_qty):'未盘' }} <small class="count-unit">{{ line.uom.name }}</small></span></td><td data-label="差异" class="count-number" :class="{increase:countDelta(line)>0,decrease:countDelta(line)<0}">{{ deltaText(line) }}</td><td v-if="phase==='review'" data-label="差异原因" class="count-reason"><template v-if="editable"><select v-model="line.difference_reason" :aria-label="line.product.name+'差异原因'" @change="markDirty"><option value="">选择原因</option><option v-for="(label,value) in countReasons" :key="value" :value="value">{{ label }}</option></select><input v-if="line.difference_reason" v-model.trim="line.difference_note" :aria-label="line.product.name+'差异说明'" :placeholder="line.difference_reason==='other'?'填写说明（必填）':'补充说明（选填）'" @input="markDirty"></template><template v-else>{{ countReasons[line.difference_reason] || '—' }}<small v-if="line.difference_note">{{ line.difference_note }}</small></template></td><td class="count-row-action"><button type="button" :aria-label="line.product.name+'详情'" @click="selectedLine=line;setDialog('line')">详情</button></td></tr><tr v-if="!visibleLines.length"><td :colspan="phase==='review'?6:5" class="count-empty">{{ !lines.length?'该范围账面为空；现场有实物时请通过“更多”补录。':phase==='review'&&!differences.length?'所有已盘数量与账面一致':'没有匹配的明细' }}</td></tr></tbody></table></div>
      <footer v-if="editable || record.state==='pending_approval'" class="count-action-bar"><span class="count-save-state">{{ record.state==='pending_approval'&&record.approval_state==='pending'?'等待负责人审批':record.approval_state==='approved'?'审批已通过，待确认入账':dirty?'有未暂存修改':lastSaved?'已暂存 '+lastSaved:'实盘为零请填写 0' }}</span><div><button v-if="editable" class="btn btn-secondary" :disabled="saving" @click="save(false)">{{ saving?'处理中…':'暂存' }}</button><template v-if="editable && phase==='entry'"><button class="btn btn-primary" :disabled="saving" @click="next">下一步：核查差异 →</button></template><template v-else-if="editable"><button class="btn btn-outline" :disabled="saving" @click="phase='entry'">返回录入</button><button class="btn btn-primary" :disabled="saving" @click="countValidation(lines)?error=countValidation(lines):setDialog('submit')">{{ differences.length?'提交差异审批':'确认完成' }}</button></template><button v-if="canManage && record.state==='pending_approval' && record.approval_state==='approved' && record.scope_locked" class="btn btn-primary" :disabled="saving" @click="setDialog('post')">确认差异入账</button><button v-if="activeStep" class="btn btn-outline" :disabled="saving" @click="setDialog('approve')">审批处理</button></div></footer>
    </template>
  </template>
  <JourneyDetailDialog v-if="dialog" :title="({create:'新建盘点',start:'开始盘点',submit:differences.length?'提交差异审批':'确认盘点完成',post:'确认差异入账',cancel:'取消本次盘点',add:'补录发现库存',line:selectedLine?.product.name,history:'单据详情',leave:'还有未暂存的实盘',approve:'盘点差异审批'})[dialog]" @close="closeDialog">
    <div class="count-dialog-content">
      <template v-if="dialog==='create'"><label>厂区<select v-model="dialogDraft.factory_id" @change="dialogDraft.location_id=''"><option value="">请选择厂区</option><option v-for="factory in options.factories" :key="factory.id" :value="factory.id">{{ factory.name }}</option></select></label><label>盘点范围<select v-model="dialogDraft.location_id" :disabled="!dialogDraft.factory_id"><option value="">请选择仓库或库位</option><option v-for="loc in listLocations" :key="loc.id" :value="loc.id">{{ locationPathLabel(loc) }}</option></select></label><p>包含所选库位及其子库位；开始后暂停该范围的实物收发。</p></template>
      <template v-else-if="dialog==='start'"><p>盘点范围：<strong>{{ locationPathLabel(record.location) }}</strong>，包含子库位。</p><p>确认后生成账面快照，暂停本范围收发。请同步安排现场暂停搬动所盘物料。</p></template>
      <template v-else-if="dialog==='submit' || dialog==='post'"><p>已盘 {{ counted }} / {{ lines.length }} 项，差异 {{ differences.length }} 项。</p><div v-for="group in groups" :key="group.unit" class="count-dialog-summary"><span v-if="group.increase">盘盈 <b>{{ number(group.increase) }} {{ group.unit }}</b></span><span v-if="group.decrease">盘亏 <b>{{ number(group.decrease) }} {{ group.unit }}</b></span></div><p v-if="!lines.length">请确认现场确实没有实物；有账外实物时应先补录。</p><p>{{ dialog==='post'?'入账后生成调整流水，并恢复本范围收发。':differences.length?'提交后等待审批，所选范围继续暂停收发。':'本单无需库存调整，确认后恢复本范围收发。' }}</p></template>
      <template v-else-if="dialog==='cancel'"><p>取消后撤销本单未结束的审批，恢复该范围收发，不调整库存。</p><label>取消原因<textarea v-model.trim="dialogDraft.reason" placeholder="填写取消原因"></textarea></label></template>
      <template v-else-if="dialog==='add'"><label>搜索商品<div class="count-dialog-search"><input v-model.trim="dialogDraft.keyword" placeholder="名称或编码" @keydown.enter.prevent="loadOptions({keyword:dialogDraft.keyword,factory_id:record.factory.id})"><button class="btn btn-outline" @click="loadOptions({keyword:dialogDraft.keyword,factory_id:record.factory.id})">查找</button></div></label><label>商品<select v-model="dialogDraft.product_id" @change="dialogDraft.lot_id='';loadOptions({keyword:dialogDraft.keyword,product_id:dialogDraft.product_id,factory_id:record.factory.id})"><option value="">选择商品</option><option v-for="product in options.products" :key="product.id" :value="product.id">{{ product.name }} · {{ product.uom }}</option></select></label><label>已有批次<select v-model="dialogDraft.lot_id"><option value="">无批次 / 选择批次</option><option v-for="lot in options.lots" :key="lot.id" :value="lot.id">{{ lot.name }}</option></select></label><label>实物库位<select v-model="dialogDraft.location_id"><option v-for="loc in addLocations" :key="loc.id" :value="loc.id">{{ locationPathLabel(loc) }}</option></select></label><label>实盘数量（商品基础单位）<input v-model="dialogDraft.counted_qty" type="number" min="0" step="any"></label><label>发现说明<textarea v-model.trim="dialogDraft.difference_note"></textarea></label><p>仅补录身份和批次已确认的实物，账面数量为零。</p></template>
      <template v-else-if="dialog==='line'"><dl><div><dt>批次</dt><dd>{{ selectedLine.lot?.name||'无批次' }}</dd></div><div><dt>库位</dt><dd>{{ locationPathLabel(selectedLine.location) }}</dd></div><div><dt>上次盘点</dt><dd>{{ selectedLine.previous_count?number(selectedLine.previous_count.counted_qty)+' '+selectedLine.uom.name:'无记录' }}</dd></div><div><dt>本次实盘</dt><dd>{{ hasCount(selectedLine)?number(selectedLine.counted_qty)+' '+selectedLine.uom.name:'未盘' }}</dd></div><div><dt>录入人 / 时间</dt><dd>{{ selectedLine.counted_by||'—' }} · {{ time(selectedLine.counted_at) }}</dd></div></dl><template v-if="editable && selectedLine.is_counted"><label>复盘数量（{{ selectedLine.uom.name }}）<input v-model="dialogDraft.counted_qty" type="number" min="0" step="any"></label><label>复盘说明<textarea v-model.trim="dialogDraft.recount_note"></textarea></label></template><p v-else-if="editable">暂存首次实盘后可记录复盘。</p><article v-for="(entry,index) in selectedLine.recounts" :key="index" class="count-history-item"><strong>{{ number(entry.before) }} → {{ number(entry.after) }} {{ selectedLine.uom.name }}</strong><small>{{ entry.by }} · {{ time(entry.at) }}</small><p>{{ entry.note }}</p></article></template>
      <template v-else-if="dialog==='history'"><dl><div><dt>单号</dt><dd>{{ record.name }}</dd></div><div><dt>负责人</dt><dd>{{ record.owner?.name }}</dd></div><div><dt>快照时间</dt><dd>{{ time(record.started_at) }}</dd></div><div><dt>完成时间</dt><dd>{{ time(record.completed_at) }}</dd></div></dl><h4 v-if="record.movements?.length">差异调整流水</h4><article v-for="move in record.movements" :key="move.id" class="count-history-item"><strong>{{ move.product }} · {{ move.direction==='increase'?'盘盈':'盘亏' }} {{ number(move.quantity) }} {{ move.uom }}</strong><small>{{ move.name }} · #{{ move.id }}</small></article><h4>处理记录</h4><article v-for="(entry,index) in [...(record.history||[])].reverse()" :key="index" class="count-history-item"><strong>{{ entry.action }}</strong><small>{{ entry.by }} · {{ time(entry.at) }}</small><p v-if="entry.detail">{{ entry.detail }}</p></article><template v-for="approval in record.approvals" :key="approval.id"><h4>审批记录 · {{ ({pending:'进行中',approved:'通过',returned:'退回',cancelled:'取消'})[approval.state] }}</h4><article v-for="step in approval.steps" :key="step.id" class="count-history-item"><strong>{{ ({production_director:'生产总监',brewery_manager:'酒厂负责人',general_manager:'总经理',warehouse:'库管',finance:'财务'})[step.role]||step.role }} · {{ ({pending:'待处理',approved:'通过',returned:'退回'})[step.state]||step.state }}</strong><small>{{ step.by||'—' }} · {{ time(step.at) }}</small><p v-if="step.comment">{{ step.comment }}</p></article></template><p v-if="record.cancel_reason">取消原因：{{ record.cancel_reason }}</p></template>
      <template v-else-if="dialog==='leave'"><p>离开将丢失尚未暂存的修改。</p></template>
      <template v-else-if="dialog==='approve'"><p>本次差异 {{ differences.length }} 项，请核对差异和原因后处理。</p><label>审批意见<textarea v-model.trim="dialogDraft.comment" placeholder="退回时必填"></textarea></label></template>
      <div v-if="dialogError" class="count-error" role="alert">{{ dialogError }}</div>
    </div>
    <template #footer><div class="count-dialog-actions"><button class="btn btn-secondary" :disabled="saving" @click="closeDialog">{{ ['line','history'].includes(dialog)?'关闭':'返回' }}</button><template v-if="dialog==='leave'"><button class="btn btn-outline" @click="dirty=false;leave()">放弃修改并离开</button><button class="btn btn-primary" :disabled="saving" @click="save(false)">先暂存</button></template><template v-else-if="dialog==='approve'"><button class="btn btn-outline" :disabled="saving" @click="review('return')">退回修改</button><button class="btn btn-primary" :disabled="saving" @click="review('approve')">审批通过</button></template><button v-else-if="!['history','line'].includes(dialog)||(dialog==='line'&&editable&&selectedLine.is_counted)" class="btn btn-primary" :disabled="saving" @click="confirmDialog">{{ saving?'处理中…':({create:'创建盘点单',start:'确认开始',submit:differences.length?'提交审批':'确认完成',post:'确认入账',cancel:'确认取消',add:'补录库存',line:'应用复盘'})[dialog] }}</button></div></template>
  </JourneyDetailDialog>
</section>
</template>

